import { useState } from 'react'
import { format } from 'date-fns'
import { Icon } from '@/design-system/Icon'
import { Card, EmptyState, Field, Sheet } from '@/components/ui'
import { useOwned } from '@/db/hooks'
import { db, newEnvelope, patch, softDelete } from '@/db/db'
import { useI18n } from '@/i18n'
import { formatRupiah, whenLabel } from '@/i18n/format'
import type { Bill, MoneyMeeting, SharedGoal, Topic } from '@/types/domain'

/**
 * Tujuan bareng (HOME-06) and ngobrol uang bulanan (FIN-03).
 *
 * Blueprint 03 §5 is specific that a goal must always carry a next action —
 * a progress bar on its own tells a couple nothing about what to do on Monday.
 * The money-meeting agenda is assembled from real records, not typed by hand.
 */

export function Goals({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const [open, setOpen] = useState(false)
  const [saveFor, setSaveFor] = useState<SharedGoal | null>(null)
  const [title, setTitle] = useState('')
  const [target, setTarget] = useState('')
  const [saved, setSaved] = useState('')
  const [next, setNext] = useState('')
  const [date, setDate] = useState('')
  const [amount, setAmount] = useState('')

  const goals = useOwned<SharedGoal>('goals', me)
  const active = (goals ?? []).filter((g) => !g.achievedAt)

  async function create() {
    const n = Number(target)
    if (!title.trim() || !Number.isFinite(n) || n <= 0) return
    await db.goals.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'goal',
      title: title.trim(),
      targetAmount: n,
      savedAmount: Number(saved) || 0,
      ...(next.trim() ? { nextAction: next.trim() } : {}),
      ...(date ? { targetDate: date } : {}),
    } as never)
    setTitle('')
    setTarget('')
    setSaved('')
    setNext('')
    setDate('')
    setOpen(false)
  }

  async function addSaving() {
    const n = Number(amount)
    if (!saveFor || !Number.isFinite(n) || n <= 0) return
    const total = saveFor.savedAmount + n
    await patch('goals', saveFor.id, {
      savedAmount: total,
      // Reaching the target is recorded, but the goal is never auto-hidden —
      // the couple decides when it is really done.
      ...(total >= saveFor.targetAmount ? { achievedAt: new Date().toISOString() } : {}),
    })
    setAmount('')
    setSaveFor(null)
  }

  return (
    <Card
      title={t('fin.goals')}
      icon="money"
      hint={t('fin.goalsHint')}
      action={
        <button className="btn btn--sm" onClick={() => setOpen(true)}>
          <Icon name="plus" size={16} /> {t('common.add')}
        </button>
      }
    >
      {active.length === 0 ? (
        <EmptyState icon="money" title={t('fin.noGoals')} hint={t('fin.noGoalsHint')} />
      ) : (
        <ul className="list">
          {active.map((g) => {
            const pct = Math.min(100, Math.round((g.savedAmount / g.targetAmount) * 100))
            return (
              <li key={g.id} className="list__item" style={{ alignItems: 'flex-start' }}>
                <Icon name="money" size={18} />
                <span className="grow stack stack--tight">
                  <strong style={{ fontSize: 14 }}>{g.title}</strong>
                  <span className="card__hint">
                    {t('fin.goalProgress', {
                      saved: formatRupiah(g.savedAmount, locale),
                      target: formatRupiah(g.targetAmount, locale),
                    })}
                    {g.targetDate ? ` · ${whenLabel(g.targetDate, t, locale)}` : ''}
                  </span>
                  {/* Progress is announced as a value, not left to the bar alone. */}
                  <span
                    className="goal__bar"
                    role="progressbar"
                    aria-valuenow={pct}
                    aria-valuemin={0}
                    aria-valuemax={100}
                    aria-label={g.title}
                  >
                    <span style={{ width: `${pct}%` }} />
                  </span>
                  {g.nextAction && (
                    <span className="chip chip--mint">
                      <Icon name="check" size={14} />
                      {g.nextAction}
                    </span>
                  )}
                </span>
                <button className="btn btn--soft btn--sm" onClick={() => setSaveFor(g)}>
                  {t('fin.addSaving')}
                </button>
                <button className="btn btn--ghost btn--sm btn--icon" onClick={() => softDelete('goals', g.id, me)}>
                  <Icon name="close" size={16} label={t('common.deleteX', { name: g.title })} />
                </button>
              </li>
            )
          })}
        </ul>
      )}

      <Sheet open={open} onClose={() => setOpen(false)} title={t('fin.goals')}>
        <div className="stack">
          <Field label={t('fin.goalName')}>
            {(p) => (
              <input
                {...p}
                type="text"
                value={title}
                placeholder={t('fin.goalPlaceholder')}
                onChange={(e) => setTitle(e.target.value)}
              />
            )}
          </Field>
          <Field label={t('fin.goalTarget')}>
            {(p) => (
              <input {...p} type="number" min="0" value={target} onChange={(e) => setTarget(e.target.value)} />
            )}
          </Field>
          <Field label={t('fin.goalSaved')} hint={t('common.optional')}>
            {(p) => <input {...p} type="number" min="0" value={saved} onChange={(e) => setSaved(e.target.value)} />}
          </Field>
          <Field label={t('fin.goalNext')} hint={t('fin.goalNextHint')}>
            {(p) => (
              <input
                {...p}
                type="text"
                value={next}
                placeholder={t('fin.goalNextPlaceholder')}
                onChange={(e) => setNext(e.target.value)}
              />
            )}
          </Field>
          <Field label={t('fin.goalDeadline')} hint={t('common.optional')}>
            {(p) => <input {...p} type="date" value={date} onChange={(e) => setDate(e.target.value)} />}
          </Field>
          <button className="btn btn--block" onClick={create} disabled={!title.trim() || !target}>
            {t('common.save')}
          </button>
        </div>
      </Sheet>

      <Sheet open={saveFor !== null} onClose={() => setSaveFor(null)} title={t('fin.addSaving')}>
        <div className="stack">
          <Field label={t('fin.savingAmount')}>
            {(p) => (
              <input {...p} type="number" min="0" value={amount} onChange={(e) => setAmount(e.target.value)} />
            )}
          </Field>
          <button className="btn btn--block" onClick={addSaving} disabled={!amount}>
            {t('common.save')}
          </button>
        </div>
      </Sheet>
    </Card>
  )
}

export function MoneyMeetingCard({ me }: { me: string }) {
  const { t, locale } = useI18n()
  const [open, setOpen] = useState(false)
  const [notes, setNotes] = useState('')

  const meetings = useOwned<MoneyMeeting>('meetings', me, (a, b) => b.date.localeCompare(a.date))
  const bills = useOwned<Bill>('bills', me)
  const goals = useOwned<SharedGoal>('goals', me)
  const topics = useOwned<Topic>('topics', me)

  // FIN-03: the agenda comes from records that already exist, so the couple
  // arrives at the conversation with the facts rather than a blank page.
  const month = format(new Date(), 'yyyy-MM')
  const agenda = {
    bills: (bills ?? []).filter((b) => b.status === 'unpaid' && b.dueDate.startsWith(month)).length,
    goals: (goals ?? []).filter((g) => !g.achievedAt).length,
    topics: (topics ?? []).filter((x) => x.status !== 'talked' && /uang|money|utang|cicil/i.test(x.title))
      .length,
  }
  const empty = agenda.bills + agenda.goals + agenda.topics === 0

  async function save() {
    await db.meetings.add({
      ...newEnvelope(me, 'C2_shared_ops'),
      kind: 'meeting',
      date: format(new Date(), 'yyyy-MM-dd'),
      agenda,
      ...(notes.trim() ? { notes: notes.trim() } : {}),
    } as never)
    setNotes('')
    setOpen(false)
  }

  return (
    <Card
      title={t('fin.meeting')}
      icon="mentalload"
      hint={t('fin.meetingHint')}
      action={
        <button className="btn btn--sm" onClick={() => setOpen(true)}>
          <Icon name="plus" size={16} /> {t('fin.startMeeting')}
        </button>
      }
    >
      {(meetings ?? []).length === 0 ? (
        <EmptyState icon="mentalload" title={t('fin.noMeeting')} hint={t('fin.noMeetingHint')} />
      ) : (
        <ul className="list">
          {(meetings ?? []).slice(0, 6).map((m) => (
            <li key={m.id} className="list__item">
              <Icon name="mentalload" size={18} />
              <span className="grow stack stack--tight">
                <strong style={{ fontSize: 14 }}>
                  {t('fin.meetingSaved', { date: whenLabel(m.date, t, locale) })}
                </strong>
                {m.notes && <span className="card__hint">{m.notes}</span>}
              </span>
            </li>
          ))}
        </ul>
      )}

      <p className="disclaimer" style={{ marginTop: 'var(--space-3)' }}>
        {t('fin.meetingDisclaimer')}
      </p>

      <Sheet open={open} onClose={() => setOpen(false)} title={t('fin.meeting')}>
        <div className="stack">
          <div className="stack stack--tight">
            <strong style={{ fontSize: 13 }}>{t('fin.meetingAgenda')}</strong>
            {empty ? (
              <p className="banner">{t('fin.agendaEmpty')}</p>
            ) : (
              <ul className="list">
                {agenda.bills > 0 && (
                  <li className="list__item">
                    <Icon name="money" size={16} />
                    <span className="grow">{t('fin.agendaBills', { n: agenda.bills })}</span>
                  </li>
                )}
                {agenda.goals > 0 && (
                  <li className="list__item">
                    <Icon name="check" size={16} />
                    <span className="grow">{t('fin.agendaGoals', { n: agenda.goals })}</span>
                  </li>
                )}
                {agenda.topics > 0 && (
                  <li className="list__item">
                    <Icon name="checkin" size={16} />
                    <span className="grow">{t('fin.agendaTopics', { n: agenda.topics })}</span>
                  </li>
                )}
              </ul>
            )}
          </div>
          <Field label={t('fin.meetingNotes')} hint={t('fin.meetingNotesHint')}>
            {(p) => <textarea {...p} value={notes} onChange={(e) => setNotes(e.target.value)} />}
          </Field>
          <button className="btn btn--block" onClick={save}>
            {t('common.save')}
          </button>
        </div>
      </Sheet>
    </Card>
  )
}
